  <script>
    const quizForm = document.getElementById("quiz-form");
    const score = document.getElementById("score");

    const answerKey = {
      q1: ["python", "javascript", "csharp"],
      q2: ["typescript", "java"],
      q3: ["go", "rust"]
    };

    const questionNames = Object.keys(answerKey);

    function getSelectedAnswers(name) {
      return [...quizForm.querySelectorAll(`input[name="${name}"]:checked`)].map((input) => input.value).sort();
    }

    function sameAnswers(selected, expected) {
      if (selected.length !== expected.length) {
        return false;
      }

      return selected.every((value, index) => value === expected[index]);
    }

    quizForm.addEventListener("submit", (event) => {
      event.preventDefault();

      let correct = 0;

      for (const name of questionNames) {
        const selected = getSelectedAnswers(name);
        const expected = [...answerKey[name]].sort();
        if (sameAnswers(selected, expected)) {
          correct += 1;
        }
      }

      const total = questionNames.length;
      const message = `You scored ${correct} out of ${total}.`;

      score.textContent = message;
      score.dataset.state = correct === total ? "success" : "warning";
    });
  </script>
